<details class="admin-create admin-menu-create"><summary>Tambah menu baru</summary><form action="/admin/menu/save" method="post" enctype="multipart/form-data" data-submit-label="Menyimpan…"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><label>Kategori<select name="category_id" required><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>"><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label>Nama<input name="name" maxlength="150" required></label><label>Harga rupiah<input name="price_idr" type="number" min="0" step="1" required></label><label>Deskripsi<textarea name="description" rows="3" maxlength="1000"></textarea></label><label class="image-upload">Foto menu <span>Opsional · JPEG, PNG, atau WebP · maks. 5 MB</span><input name="image" type="file" accept="image/jpeg,image/png,image/webp" data-image-input><img class="image-preview" src="/assets/img/menu-placeholder.svg" alt="Pratinjau foto menu baru" data-image-preview></label><button class="btn btn-primary" type="submit">Tambah menu</button></form></details>
<div class="admin-menu-grid"><?php foreach ($items as $item): ?><article><img src="<?= e($item['image_path'] ?: '/assets/img/menu-placeholder.svg') ?>" alt="<?= e($item['name']) ?>" width="240" height="240"><div class="admin-menu-card-head"><span><?= e($item['category_name']) ?></span><h2><?= e($item['name']) ?></h2><strong><?= e(rupiah((int) $item['price_idr'])) ?></strong></div><details><summary>Edit rincian</summary><form action="/admin/menu/save" method="post" enctype="multipart/form-data" data-submit-label="Menyimpan…"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><label>Kategori<select name="category_id"><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (int) $item['category_id'] === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label>Nama<input name="name" maxlength="150" value="<?= e($item['name']) ?>" required></label><label>Harga<input name="price_idr" type="number" min="0" value="<?= (int) $item['price_idr'] ?>" required></label><label>Deskripsi<textarea name="description" rows="3" maxlength="1000"><?= e($item['description']) ?></textarea></label><label class="image-upload">Ganti foto <span>Biarkan kosong untuk mempertahankan foto sekarang.</span><input name="image" type="file" accept="image/jpeg,image/png,image/webp" data-image-input><img class="image-preview" src="<?= e($item['image_path'] ?: '/assets/img/menu-placeholder.svg') ?>" alt="Pratinjau foto <?= e($item['name']) ?>" data-image-preview></label><button class="btn btn-light" type="submit">Simpan rincian</button></form></details><div class="admin-card-actions"><form action="/admin/menu/toggle" method="post"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="field" value="is_visible"><button type="submit"><?= (int) $item['is_visible'] === 1 ? 'Sembunyikan' : 'Tampilkan' ?></button></form><form action="/admin/menu/toggle" method="post"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="field" value="is_available"><button type="submit"><?= (int) $item['is_available'] === 1 ? 'Tandai habis' : 'Tandai tersedia' ?></button></form></div></article><?php endforeach; ?></div>
</section>
